import{_ as i,o as s,c as l,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/reportdesigner/report-berichtsassistent-1.png",o="/bilder/reportdesigner/report-berichtsassistent-2.png",p="/bilder/reportdesigner/report-berichtsassistent-3.png",d="/bilder/reportdesigner/report-berichtsassistent-4.png",u="/bilder/reportdesigner/report-berichtsassistent-5.png",c="/bilder/reportdesigner/report-berichtsassistent-6.png",g="/bilder/reportdesigner/report-berichtsassistent-7.png",h="/bilder/reportdesigner/report-berichtsassistent-8.png",m="/bilder/reportdesigner/report-anpassen-1.png",b="/bilder/reportdesigner/report-anpassen-2.png",f="/bilder/reportdesigner/report-anpassen-3.png",k="/bilder/reportdesigner/report-anpassen-6.png",_="/bilder/reportdesigner/report-anpassen-4.png",w="/bilder/reportdesigner/report-anpassen-5.png",z="/bilder/reportdesigner/report-anpassen-7.png",v="/bilder/reportdesigner/report-anpassen-8.png",S="/bilder/reportdesigner/report-anpassen-9.png",D="/bilder/reportdesigner/report-anpassen-10.png",T="/bilder/reportdesigner/report-anpassen-11.png",B="/bilder/reportdesigner/report-anpassen-12.png",A="/bilder/reportdesigner/report-anpassen-13.png",E="/bilder/reportdesigner/report-anpassen-14.png",y="/bilder/reportdesigner/report-anpassen-15.png",F="/bilder/reportdesigner/report-anpassen-16.png",G=JSON.parse('{"title":"Einen Report mit dem Berichtsassistenten erstellen","description":"","frontmatter":{"title":"Einen Report mit dem Berichtsassistenten erstellen","source_pageid":1566,"source_revision":6681},"headers":[],"relativePath":"reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.md","filePath":"reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.md"}'),R={name:"reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.md"};function x(P,t,C,V,I,L){return s(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="einen-report-mit-dem-berichtsassistenten-erstellen" tabindex="-1">Einen Report mit dem Berichtsassistenten erstellen <a class="header-anchor" href="#einen-report-mit-dem-berichtsassistenten-erstellen" aria-label="Permalink to &quot;Einen Report mit dem Berichtsassistenten erstellen&quot;">​</a></h1><p>Lassen Sie den Berichtsassistenten eine erste Liste erzeugen. Anschließend passen Sie Layout, Gruppenwechsel, Systemvariablen und Zeilenzähler an.</p><p>In den bisherigen Beispielen wurden Reports und ihre Bestandteile manuell erstellt. Der <strong>Berichtsassistent</strong> in <strong>SchILD-NRW 3</strong> automatisiert große Teile dieses Prozesses: Er kann Datenfelder auswählen, gruppieren, sortieren und erste Formatierungen vornehmen. Dies spart Zeit und eignet sich gut für Standardlisten, die direkt nutzbar sind oder anschließend leicht angepasst werden können.</p><p>Im folgenden Beispiel wird eine einfache Liste erzeugt und anschließend optimiert. Dies dient zugleich als Einführungsbeispiel für wichtige Werkzeuge im Reporteditor.</p><h2 id="_1-erstellung-des-reports" tabindex="-1">1. Erstellung des Reports <a class="header-anchor" href="#_1-erstellung-des-reports" aria-label="Permalink to &quot;1. Erstellung des Reports&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-berichtsassistent-1.png"><img src="'+a+'" alt="Erzeugen eines neuen Reports." loading="lazy"></a></p><p><em>Erzeugen eines neuen Reports.</em></p><p>Öffnen Sie im <strong>Reportdesigner</strong> das Menü <strong>Datei → Neu…</strong> oder drücken Sie <strong>Strg + N</strong>. Wie Sie den Reportdesigner aufrufen, erläutert <a href="/reporting/reportdesigner/reportdesigner.html">Den Reportdesigner öffnen und verwenden</a>.</p><p><a href="/bilder/reportdesigner/report-berichtsassistent-2.png"><img src="'+o+'" alt="Aufruf des Berichtsassistenten." loading="lazy"></a></p><p><em>Aufruf des Berichtsassistenten.</em></p><p>Im nächsten Schritt wird <strong>Berichtsassistent</strong> gewählt und mit <strong>Ok</strong> bestätigt.</p><p><a href="/bilder/reportdesigner/report-berichtsassistent-3.png"><img src="'+p+'" alt="Aufruf des Berichtsassistenten." loading="lazy"></a></p><p><em>Aufruf des Berichtsassistenten.</em></p><p>Wählen Sie die <strong>Datenquelle Schueler</strong>. Eine Datenquelle stellt die Datenfelder für den Report bereit; für die hier gezeigte Schülerliste benötigen Sie die Schülerdaten.</p><p>Darunter stehen nun die zur Verfügung stehenden <strong>Datenfelder</strong>. Mit einem Doppelklick oder per Klick auf <strong>&gt;</strong> werden Felder nach <strong>Ausgewählte Felder</strong> übernommen. Mit <strong>&lt;</strong> können Felder wieder entfernt werden.</p><p>Die Pfeilsymbole rechts verändern die Reihenfolge der Felder. Die obersten Felder stehen später in der erzeugten Liste links.</p>',16),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Sollen Felder nur für eine Gruppierung verwendet werden, aber nicht in der Liste erscheinen, können sie trotzdem hier ausgewählt werden.")],-1),r('<p>Der Bericht kann bereits mit <strong>Fertigstellen</strong> erzeugt werden. Im Beispiel werden jedoch zusätzliche Funktionen erläutert, daher wird <strong>Weiter &gt;</strong> gewählt.</p><p><a href="/bilder/reportdesigner/report-berichtsassistent-4.png"><img src="'+d+'" alt="Datenfelder werden genutzt, um Schüler zu gruppieren." loading="lazy"></a></p><p><em>Datenfelder werden genutzt, um Schüler zu gruppieren.</em></p><p>Im nächsten Schritt können Daten gruppiert werden. Durch Doppelklick wurde das Feld <strong>Klasse</strong> in den Bereich <strong>Gruppen</strong> verschoben. Dies erzeugt später eine nach Klassen sortierte Liste.</p>',4),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Eine Gruppierung nach "),e("strong",null,"Klasse"),n(" oder nach "),e("strong",null,"Alter"),n(" ist typischer Anwendungsfall.")]),e("p",null,"Eine Gruppierung nach Vornamen oder Geburtsdatum wäre technisch möglich, aber wenig sinnvoll.")],-1),r('<p>Ohne Gruppierung würde <strong>Klasse</strong> als normales Feld in der Liste erscheinen.</p><p><a href="/bilder/reportdesigner/report-berichtsassistent-5.png"><img src="'+u+'" alt="Auswahl eines Layouts und der Seitenausrichtung." loading="lazy"></a></p><p><em>Auswahl eines Layouts und der Seitenausrichtung.</em></p><p>Nun wird ein Layout gewählt. Im Beispiel wurde <strong>Links ausrichten</strong> gewählt.</p><p>Bei der Wahl der Seitenausrichtung ist Folgendes zu bedenken:</p><ul><li>viele Datenfelder oder lange Inhalte → <strong>Querformat</strong> sinnvoll</li><li>typische Klassengrößen → passen im Querformat häufig nicht auf A4</li></ul><p><a href="/bilder/reportdesigner/report-berichtsassistent-6.png"><img src="'+c+'" alt="Wahl eines Stils." loading="lazy"></a></p><p><em>Wahl eines Stils.</em></p><p>Im nächsten Fenster wird ein Stil gewählt, hier <strong>sachlich</strong>.</p>',9),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Wenn kein Farbdruck benötigt wird, kann Schwarzweiß sinnvoll sein, um unnötige Farbdrucke zu vermeiden.")],-1),r('<p><a href="/bilder/reportdesigner/report-berichtsassistent-7.png"><img src="'+g+'" alt="Wahl des Modus, in dem sich der Editor nach Abschluss des Assistenten befindet." loading="lazy"></a></p><p><em>Wahl des Modus, in dem sich der Editor nach Abschluss des Assistenten befindet.</em></p><p>Zum Abschluss wird gewählt, ob der Report im <strong>Editor</strong> oder in der <strong>Vorschau</strong> geöffnet wird. Ein Wechsel zwischen beiden Ansichten ist jederzeit möglich.</p><p><a href="/bilder/reportdesigner/report-berichtsassistent-8.png"><img src="'+h+'" alt="Das vorläufig fertige Ergebnis." loading="lazy"></a></p><p><em>Das vorläufig fertige Ergebnis.</em></p><p>Der erzeugte Report enthält bereits:</p><ul><li>alle gewählten Felder</li><li>eine Gruppierung nach Klasse</li><li>eine saubere Listenstruktur</li><li>ein Druckdatum und eine Seitenzahl im Fuß</li></ul><p>Das Layout ist verwendbar – lässt sich jedoch weiter verbessern.</p><h2 id="_2-anpassen-des-reports" tabindex="-1">2. Anpassen des Reports <a class="header-anchor" href="#_2-anpassen-des-reports" aria-label="Permalink to &quot;2. Anpassen des Reports&quot;">​</a></h2><p>Die folgenden Anpassungen dienen als Beispiel und zeigen typische Werkzeuge des Reporteditors.</p><h3 id="einfache-anpassungen-zu-layout-linien-und-schriften" tabindex="-1">Einfache Anpassungen zu Layout, Linien und Schriften <a class="header-anchor" href="#einfache-anpassungen-zu-layout-linien-und-schriften" aria-label="Permalink to &quot;Einfache Anpassungen zu Layout, Linien und Schriften&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-anpassen-1.png"><img src="'+m+'" alt="Identifizierte Probleme." loading="lazy"></a></p><p><em>Identifizierte Probleme.</em></p><p>Folgende Punkte sollen verbessert werden:</p><ul><li>Der <strong>Titel</strong> wird nur auf der ersten Seite ausgegeben – bei Klassenlisten oft unerwünscht.</li><li>Die Felder sollen weiter <strong>nach links verschoben</strong> werden, um rechts Platz für Eintragungen zu schaffen.</li><li>Farben sollen in <strong>Schwarzweiß</strong> geändert werden, um Farbdrucke zu vermeiden.</li></ul><p><a href="/bilder/reportdesigner/report-anpassen-2.png"><img src="'+b+'" alt="Deaktivieren des Titels." loading="lazy"></a></p><p><em>Deaktivieren des Titels.</em></p><p>Der Titel kann über <strong>Bericht</strong> deaktiviert werden. Ein <strong>Titel</strong> erscheint nur auf der ersten Seite, die <strong>Zusammenfassung</strong> auf der letzten Seite. <strong>Kopf</strong> und <strong>Fuß</strong> erscheinen auf jeder Seite.</p>',18),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Subreports, z. B. Zeugnisblöcke, benötigen meist keine eigenen Köpfe oder Füße.")],-1),e("p",null,[n("Da eine "),e("strong",null,"Gruppe"),n(" (Klasse) definiert wurde, erzeugt der Report zusätzlich "),e("strong",null,"Gruppenköpfe"),n(" und "),e("strong",null,"Gruppenfüße"),n(". Diese erscheinen am Beginn bzw. Ende jeder Gruppe.")],-1),e("p",null,"Zum Verschieben mehrerer Felder können diese markiert werden.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Mehrfachauswahl: Klicken Sie das erste Feld an. Halten Sie danach die "),e("strong",null,"Umschalttaste (Shift)"),n(" gedrückt und klicken Sie die weiteren Felder an.")])],-1),r('<p>Im Beispiel verschieben Sie die Beschriftungsfelder (<strong>Labels</strong>) im Kopf und die drei Datenfelder (<strong>DBText</strong>) im <strong>Detailbereich</strong> gemeinsam. Der Detailbereich wird für jeden Datensatz ausgegeben, hier also für jede Person der Liste.</p><p><a href="/bilder/reportdesigner/report-anpassen-3.png"><img src="'+f+'" alt="Umfärben der bunten Felder." loading="lazy"></a></p><p><em>Umfärben der bunten Felder.</em></p><p>Mit <strong>Shift + Klick</strong> werden Felder in Blau markiert (z. B. Klassen und Druckdatum). Mit dem <strong>Schriftfarbenwerkzeug</strong> werden sie auf Schwarz geändert.</p>',4),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Das Umfärben lässt sich vermeiden, wenn beim Berichtsassistenten ein Graustufen-Layout gewählt wird.")],-1),e("p",null,[n("Das Feld "),e("strong",null,"GeschlechtMW"),n(" wird im Gruppenkopf beschriftet – der Datenbankname ist jedoch unschön. Daher wird der sichtbare Titel auf "),e("strong",null,"Geschlecht"),n(" geändert.")],-1),e("p",null,[e("a",{href:"/bilder/reportdesigner/report-anpassen-6.png"},[e("img",{src:k,alt:"Einfügen von Linien.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Einfügen von Linien.")],-1),e("p",null,"Um handschriftliche Ergänzungen zu ermöglichen, werden Trennlinien gesetzt.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Horizontale Linien gehören oben in den Detailbereich, damit jeder neue Eintrag die Linie unter dem vorherigen erzeugt.")],-1),e("p",null,[n("Ein Rechtsklick und die Funktion "),e("strong",null,"Breite der Stammkomponente"),n(" setzen die Linie automatisch auf die Breite des Detailbereichs.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Das Platzieren von Linien, Flächen und Farben kann viel Zeit kosten – der "),e("strong",null,"Berichtsbaum"),n(" hilft, Felder gezielt auszuwählen.")])],-1),e("p",null,"Im Beispiel wurden zusätzlich:",-1),e("ul",null,[e("li",null,"beide Felder zum Alter linksbündig gestellt"),e("li",null,"alle Schriften modernisiert")],-1),e("p",null,[e("a",{href:"/bilder/reportdesigner/report-anpassen-4.png"},[e("img",{src:_,alt:"Der Report im Editormodus.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Der Report im Editormodus.")],-1),e("p",null,"Der Report erscheint nun im Editormodus gut strukturiert.",-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Weitere mögliche Felder sind "),e("strong",null,"Bilder"),n(", "),e("strong",null,"Formen"),n(" oder "),e("strong",null,"Checkboxen"),n(".")])],-1),r('<p><a href="/bilder/reportdesigner/report-anpassen-5.png"><img src="'+w+'" alt="Der Report in der Vorschau." loading="lazy"></a></p><p><em>Der Report in der Vorschau.</em></p><p>In der Vorschau ergibt sich ein funktionales Ergebnis.</p><h2 id="_3-seitenwechsel-systemvariablen-und-zahler-erganzen" tabindex="-1">3. Seitenwechsel, Systemvariablen und Zähler ergänzen <a class="header-anchor" href="#_3-seitenwechsel-systemvariablen-und-zahler-erganzen" aria-label="Permalink to &quot;3. Seitenwechsel, Systemvariablen und Zähler ergänzen&quot;">​</a></h2><p>Folgende Erweiterungen werden ergänzt:</p><ul><li>automatischer Seitenwechsel je Klasse</li><li>Zurücksetzen der Seitenzahlen bei Gruppenwechsel</li><li>Nutzung von Systemvariablen</li><li>Zeilenzähler im Detailbereich</li></ul><h3 id="gruppen-fur-seitenwechsel" tabindex="-1">Gruppen für Seitenwechsel <a class="header-anchor" href="#gruppen-fur-seitenwechsel" aria-label="Permalink to &quot;Gruppen für Seitenwechsel&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-anpassen-7.png"><img src="'+z+'" alt="Aufrufen der Gruppeneinstellungen." loading="lazy"></a></p><p><em>Aufrufen der Gruppeneinstellungen.</em></p><p>Da der Report bereits nach <strong>Klasse</strong> gruppiert, wird diese Gruppe für Seitenwechsel genutzt. Dies erfolgt über <strong>Bericht → Gruppen…</strong>.</p><p><a href="/bilder/reportdesigner/report-anpassen-8.png"><img src="'+v+'" alt="Definition, dass die Gruppe Schueler.Klasse zum Seitenwechsel genutzt werden soll." loading="lazy"></a></p><p><em>Definition, dass die Gruppe Schueler.Klasse zum Seitenwechsel genutzt werden soll.</em></p><p>Unter <strong>Bei Gruppenwechsel</strong> können u. a. gewählt werden:</p><ul><li><strong>Neue Seite beginnen</strong></li><li><strong>Seitennummerierung zurücksetzen</strong></li></ul>',14),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Wenn Schülerdaten komplexer sind, kann zusätzlich nach "),e("strong",null,"Schueler.ID"),n(" gruppiert werden. Mit "),e("strong",null,"Gruppe zusammenhalten"),n(" werden halbe Datensätze nicht geteilt.")])],-1),r('<h3 id="systemvariablen" tabindex="-1">Systemvariablen <a class="header-anchor" href="#systemvariablen" aria-label="Permalink to &quot;Systemvariablen&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-anpassen-9.png"><img src="'+S+'" alt="Verwendung von Systemvariablen." loading="lazy"></a></p><p><em>Verwendung von Systemvariablen.</em></p><p>Eine <strong>Systemvariable</strong> wurde bereits vom Assistenten gesetzt: das <strong>Druckdatum</strong> im Fuß. Eine weitere sinnvolle Variable ist der <strong>Dokumenten-Name</strong>, mit dem der Dateiname des Reports ausgegeben wird.</p><p>Platzieren Sie eine Systemvariable wie ein anderes Feld und wählen Sie anschließend die gewünschte Angabe in der Auswahlliste. Zur Verfügung stehen unter anderem:</p><ul><li>Druckdatum (mit/ohne Zeit)</li><li>Seitenzahlen</li><li>Dokumenten-Name</li></ul><h3 id="zeilennummerierung-per-zahler" tabindex="-1">Zeilennummerierung per Zähler <a class="header-anchor" href="#zeilennummerierung-per-zahler" aria-label="Permalink to &quot;Zeilennummerierung per Zähler&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-anpassen-10.png"><img src="'+D+'" alt="Einfügen des DBCalc-Feldes." loading="lazy"></a></p><p><em>Einfügen des <strong>DBCalc</strong>-Feldes.</em></p><p>Um Zeilen zu nummerieren, wird Platz geschaffen und ein <strong>DBCalc</strong>-Feld gesetzt. <strong>DBCalc</strong> dient für datenbankbasierte Berechnungen.</p>',10),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Für präzises Ausrichten kann der "),e("strong",null,"Zoom"),n(" erhöht und der Detailbereich temporär vergrößert werden.")])],-1),r('<p><a href="/bilder/reportdesigner/report-anpassen-11.png"><img src="'+T+'" alt="Wahl von Laufender Zähler nach Rechtsklick." loading="lazy"></a></p><p><em>Wahl von <strong>Laufender Zähler</strong> nach Rechtsklick.</em></p><p>Per Rechtsklick wird <strong>Laufender Zähler</strong> ausgewählt.</p><p><a href="/bilder/reportdesigner/report-anpassen-12.png"><img src="'+B+'" alt="Zurücksetzen des Zählers bei Gruppenwechsel." loading="lazy"></a></p><p><em>Zurücksetzen des Zählers bei Gruppenwechsel.</em></p><p>Wie bei den Seitenzahlen wird der Zähler bei <strong>Klasse</strong> zurückgesetzt.</p><p><a href="/bilder/reportdesigner/report-anpassen-13.png"><img src="'+A+'" alt="Der Zähler funktioniert technisch…" loading="lazy"></a></p><p><em>Der Zähler funktioniert technisch…</em></p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die Zeilenhöhe war zu groß, da der Detailbereich nicht wieder verkleinert wurde. Dies wurde korrigiert.")],-1),r('<p><a href="/bilder/reportdesigner/report-anpassen-14.png"><img src="'+E+'" alt="Veränderung des Anzeigeformats." loading="lazy"></a></p><p><em>Veränderung des Anzeigeformats.</em></p><p>Über <strong>Anzeigeformat</strong> wird das Ausgabeformat definiert.</p><p><a href="/bilder/reportdesigner/report-anpassen-15.png"><img src="'+y+'" alt="Eingabe des gewünschten Formats." loading="lazy"></a></p><p><em>Eingabe des gewünschten Formats.</em></p><p>Für die Ausgabe „5.“ wird z. B. <strong>#&#39;.</strong> gewählt. <strong>#</strong> steht für die laufende Zahl.</p>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Das Hochkomma findet sich auf derselben Taste wie »#«.")],-1),e("p",null,[e("a",{href:"/bilder/reportdesigner/report-anpassen-16.png"},[e("img",{src:F,alt:"Das Ergebnis.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Das Ergebnis.")],-1),e("p",null,"Das Ergebnis ist eine nach Klassen getrennte Liste mit Zeilennummerierung. Welche Klassen oder Gruppen verarbeitet werden, wird zuvor in SchILD-NRW 3 über den Container ausgewählt.",-1),e("p",null,"Je nach Bedarf können weitere Anpassungen erfolgen (z. B. größere Zeilenhöhe).",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einen_neuen_Report_mit_dem_Berichtsassistenten_erstellen",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6681.")],-1)])])}const M=i(R,[["render",x]]);export{G as __pageData,M as default};
